const items = $input.all().map(i => i.json);

// Sort by estimated revenue / sold count descending
const sorted = items.sort((a, b) => (b.sold_count || 0) - (a.sold_count || 0));
const topWinner = sorted[0] || {};

return [{
  json: {
    analyzed_count: items.length,
    top_winner_id: String(topWinner.product_id || "1732201471924867654"),
    top_winner_title: topWinner.title || "N/A",
    top_winner_price: topWinner.current_price || 0,
    top_winner_sold: topWinner.sold_count || 0,
    top_winner_revenue: topWinner.estimated_revenue || 0,
    top_winner_seller: topWinner.seller_name || "N/A",
    top_winner_url: topWinner.product_url || "",
    top_3_products: sorted.slice(0, 3)
  }
}];

